import { mutation } from "./_generated/server";

export const backfillPriority = mutation({
  args: {},
  handler: async (ctx) => {
    const tasks = await ctx.db.query("tasks_zr_wo4sgv8").collect();
    for (const task of tasks) {
      if (task.priority === undefined) {
        await ctx.db.patch(task._id, { priority: "medium" });
      }
    }
  },
});

import { query } from "./_generated/server";

export const getAll = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query("tasks_zr_wo4sgv8").collect();
  },
});

const { ConvexHttpClient } = require("convex/browser");
const fs = require("fs");
const path = require("path");

async function main() {
  const client = new ConvexHttpClient(process.env.CONVEX_URL);
  const result = await client.query("queries:getAll");
  fs.writeFileSync(
    path.join("/home/user/project/output.log"),
    JSON.stringify(result)
  );
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
